import{_ as t,o as i,c as n,a0 as o}from"./chunks/framework.CShDTZbC.js";const p=JSON.parse('{"title":"Phase 3A: Open Technical Questions & Implementation Risks","description":"","frontmatter":{},"headers":[],"relativePath":"phase-3-open-questions.md","filePath":"phase-3-open-questions.md"}'),a={name:"phase-3-open-questions.md"};function s(r,e,l,c,h,d){return i(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="phase-3a-open-technical-questions-implementation-risks" tabindex="-1">Phase 3A: Open Technical Questions &amp; Implementation Risks <a class="header-anchor" href="#phase-3a-open-technical-questions-implementation-risks" aria-label="Permalink to &quot;Phase 3A: Open Technical Questions &amp; Implementation Risks&quot;">​</a></h1><p>Before beginning full implementation of the architecture, we must address these open questions and technical risks via targeted experiments.</p><h2 id="_1-tool-call-parsing-reliability" tabindex="-1">1. Tool Call Parsing Reliability <a class="header-anchor" href="#_1-tool-call-parsing-reliability" aria-label="Permalink to &quot;1. Tool Call Parsing Reliability&quot;">​</a></h2><ul><li><strong>Risk:</strong> Can the standard Gemini/OpenAI SDK consistently output complex file patch JSON objects without syntax errors? Antigravity handles this natively, but our runner must parse raw LLM output.</li><li><strong>Mitigation Experiment:</strong> We need to build a tiny LLM script that tries to patch a file 50 times in a row and measure the syntax error rate.</li></ul><h2 id="_2-docker-execution-latency" tabindex="-1">2. Docker Execution Latency <a class="header-anchor" href="#_2-docker-execution-latency" aria-label="Permalink to &quot;2. Docker Execution Latency&quot;">​</a></h2><ul><li><strong>Risk:</strong> Phase 2D.5 proved that iterative execution is necessary. If spinning up a Docker container and mounting the volume takes 10 seconds per iteration, a 5-iteration fix will take an unacceptably long time.</li><li><strong>Mitigation Experiment:</strong> Should we use <code>docker exec</code> on a persistent background container for the duration of the agent loop, rather than <code>docker run</code> for every single command?</li></ul><h2 id="_3-context-truncation-strategy" tabindex="-1">3. Context Truncation Strategy <a class="header-anchor" href="#_3-context-truncation-strategy" aria-label="Permalink to &quot;3. Context Truncation Strategy&quot;">​</a></h2><ul><li><strong>Risk:</strong> Compilers (like <code>tsc</code> or <code>gcc</code>) can output 50,000 lines of logs on failure. Feeding this entire log to the LLM will exhaust the context window and massively inflate token costs.</li><li><strong>Mitigation Experiment:</strong> We must determine the optimal log trimming strategy. Does the agent need the first 50 lines (the core error) or the last 50 lines (the stack trace exit)? Usually, compiler errors are at the top, while runtime stack traces are at the bottom.</li></ul><h2 id="_4-native-os-vs-docker-sandbox" tabindex="-1">4. Native OS vs. Docker Sandbox <a class="header-anchor" href="#_4-native-os-vs-docker-sandbox" aria-label="Permalink to &quot;4. Native OS vs. Docker Sandbox&quot;">​</a></h2><ul><li><strong>Risk:</strong> If we mount the user&#39;s host directory into a Docker sandbox, fixing file permissions (e.g., <code>chmod +x</code> inside the container) might create file permission issues on the user&#39;s host machine.</li><li><strong>Open Question:</strong> Do we copy the files into the container, let the agent fix them, and then explicitly copy back the patched files to the host?</li></ul><h2 id="_5-infinite-llm-loops" tabindex="-1">5. Infinite LLM Loops <a class="header-anchor" href="#_5-infinite-llm-loops" aria-label="Permalink to &quot;5. Infinite LLM Loops&quot;">​</a></h2><ul><li><strong>Risk:</strong> What happens if the LLM issues a command that hangs indefinitely (e.g., a dev server <code>npm run dev</code> that doesn&#39;t return an exit code)?</li><li><strong>Mitigation:</strong> The runner MUST wrap all <code>execute_command</code> calls in a strict timeout (e.g., 10 seconds). If it times out, the runner kills the process and tells the LLM &quot;Command timed out.&quot;</li></ul>',12)])])}const m=t(a,[["render",s]]);export{p as __pageData,m as default};
